package com.bank.pipeline;

// Models a Groovy Shared Library step reused by both pipeline styles.
public class SharedLibrary {
    // Equivalent to a global var step: bankDeploy(service, env)
    public static Stage bankDeploy(String service, String env) {
        return new Stage("Deploy " + env,
                "kubectl -n " + env + " set image deploy/" + service
                + " " + service + "=registry.bank.local/" + service + ":${TAG}");
    }
}
