package com.bank.pipeline;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Declarative: a FIXED, readable structure of stages plus a post action.
public class DeclarativePipeline {
    private static final Logger log = Logger.getLogger(DeclarativePipeline.class.getName());
    private final String agentLabel;
    private final List<Stage> stages = new ArrayList<>();
    private String postAlways;

    public DeclarativePipeline(String agentLabel) { this.agentLabel = agentLabel; }

    // Declarative-style builder: each call is like a 'stage { steps { } }' block.
    public DeclarativePipeline stage(Stage stage) { stages.add(stage); return this; }
    public DeclarativePipeline post(String always) { this.postAlways = always; return this; }

    public void run() {
        log.info(() -> "pipeline { agent { label '" + agentLabel + "' } }");
        for (Stage s : stages) {
            log.info(() -> "  stage('" + s.getName() + "') -> " + s.getAction());
        }
        if (postAlways != null) {
            log.info(() -> "  post { always { " + postAlways + " } }");
        }
    }
}
