// ─── File: src/main/java/com/bank/pipeline/ScriptedPipeline.java ───
package com.bank.pipeline;

import java.util.List;
import java.util.logging.Logger;

// Scripted: imperative Groovy-like logic that BUILDS stages at runtime.
public class ScriptedPipeline {
    private static final Logger log = Logger.getLogger(ScriptedPipeline.class.getName());

    public void run(List<String> services, String env) {
        log.info("node {");
        // This loop is the whole point of Scripted: dynamic stages.
        for (String service : services) {
            Stage deploy = SharedLibrary.bankDeploy(service, env);
            log.info(() -> "  stage('" + deploy.getName() + " " + service + "') -> "
                    + deploy.getAction());
        }
        log.info("}");
    }
}
```

