// ─── File: src/main/java/com/bank/pipeline/PipelineStylesDemo.java ───
package com.bank.pipeline;

import java.util.List;
import java.util.logging.*;

public class PipelineStylesDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PipelineLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(PipelineStylesDemo.class.getName());

        log.info("=== DECLARATIVE (fixed, readable) ===");
        new DeclarativePipeline("k8s")
                .stage(new Stage("Build", "mvn clean package"))
                .stage(new Stage("Test",  "mvn test"))
                .stage(SharedLibrary.bankDeploy("transfer-service", "qa"))
                .post("archiveArtifacts 'target/*.jar'; junit 'target/surefire-reports/*.xml'")
                .run();

        log.info("=== SCRIPTED (dynamic stages via a loop) ===");
        new ScriptedPipeline().run(
                List.of("transfer-service", "account-service", "fraud-service"), "dev");
    }
}

// ─── Would be in PipelineLogFormatter.java in a real project ───
class PipelineLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
