```groovy
// ─── File: Jenkinsfile.declarative ───
@Library('bank-shared-lib') _
pipeline {
  agent { label 'k8s' }
  environment { TAG = "${GIT_COMMIT}" }
  stages {
    stage('Build') { steps { sh 'mvn clean package' } }
    stage('Test')  { steps { sh 'mvn test' } }
    stage('Deploy QA') {
      when { branch 'qa' }
      steps { bankDeploy service: 'transfer-service', env: 'qa' }   // shared lib step
    }
  }
  post {
    always  { archiveArtifacts 'target/*.jar'; junit 'target/surefire-reports/*.xml' }
    failure { slackSend channel: '#bank-ci', message: "Build failed: ${env.BUILD_URL}" }
  }
}
```

```groovy
// ─── File: Jenkinsfile.scripted ───
@Library('bank-shared-lib') _
node('k8s') {
  def services = ['transfer-service', 'account-service', 'fraud-service']
  stage('Build all') { sh 'mvn clean package' }
  // Dynamic: one deploy stage per service, decided at runtime.
  for (svc in services) {
    stage("Deploy ${svc}") {
      bankDeploy service: svc, env: 'dev'
    }
  }
}
